import{_ as a,o as t,c as r,a5 as s}from"./chunks/framework.DrDMl0tG.js";const m=JSON.parse('{"title":"Server Example: Sim Control Demo","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/sim_control_demo.md","filePath":"sections/examples/server/sim_control_demo.md"}'),o={name:"sections/examples/server/sim_control_demo.md"};function i(n,e,l,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="server-example-sim-control-demo" tabindex="-1">Server Example: Sim Control Demo <a class="header-anchor" href="#server-example-sim-control-demo" aria-label="Permalink to &quot;Server Example: Sim Control Demo&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Demonstrates the interactive simulation-control requests supported by <code>RaisimServer</code> and the rayrai TCP viewer: pause, resume, single- or multi-step, external force and torque application, single-body pose edits, and articulated generalized-coordinate edits.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>sim_control_demo</code>. The source is <code>examples/src/server/sim_control_demo.cpp</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Start the viewer, then run the build-tree example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_tcp_viewer</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/sim_control_demo</span></span></code></pre></div><p>On Windows, run <code>sim_control_demo.exe</code> instead. Select <code>anymal</code> or <code>poke_box</code> in the viewer. Use the Objects tab to pause, resume, and step, or use the force and pose tools described in <a href="./../../RayraiTcpViewer.html">Rayrai TCP Viewer</a>.</p><h2 id="security-boundary" tabindex="-1">Security Boundary <a class="header-anchor" href="#security-boundary" aria-label="Permalink to &quot;Security Boundary&quot;">​</a></h2><p>The server binds to <code>127.0.0.1</code> by default. Simulation-control requests are not authenticated: a client that can reach the server can change the world. Keep the loopback default unless every host on the reachable network is trusted. Calling <code>server.setBindLoopbackOnly(false)</code> explicitly opts into listening on all interfaces.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Creates a PD-controlled ANYmal named <code>anymal</code> for generalized-coordinate edits.</li><li>Creates a dynamic box named <code>poke_box</code> for force, torque, and pose edits.</li><li>Uses <code>RaisimServer::integrateWorldThreadSafe()</code>; negotiated viewer requests are applied inside the server&#39;s synchronization boundary before integration.</li><li>Runs until terminated by the user.</li></ul>`,13)])])}const u=a(o,[["render",i]]);export{m as __pageData,u as default};
